Sure, to define an async thunk for saving data, you can follow a similar pattern as the `fetchData` example. Let's create an async thunk called `saveData` in the `comparableDataSlice.js` file:

```javascript
// comparableDataSlice.js
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import axios from 'axios';

// Define the initial state
const initialState = {
  data: [],
  status: 'idle', // 'idle', 'loading', 'succeeded', 'failed'
  error: null,
};

// Define an async thunk for fetching data
export const fetchData = createAsyncThunk('comparableData/fetchData', async () => {
  try {
    const response = await axios.get('/api/comparableData');
    return response.data;
  } catch (error) {
    throw error;
  }
});

// Define an async thunk for saving data
export const saveData = createAsyncThunk('comparableData/saveData', async (dataToSave) => {
  try {
    const response = await axios.post('/api/comparableData', dataToSave);
    return response.data;
  } catch (error) {
    throw error;
  }
});

// Define the slice
const comparableDataSlice = createSlice({
  name: 'comparableData',
  initialState,
  reducers: {
    // Other synchronous actions can be added here if needed
  },
  extraReducers: (builder) => {
    // Handle the pending state while fetching data
    builder.addCase(fetchData.pending, (state) => {
      state.status = 'loading';
    });

    // Handle the success state after successfully fetching data
    builder.addCase(fetchData.fulfilled, (state, action) => {
      state.status = 'succeeded';
      state.data = action.payload;
    });

    // Handle the error state if there's an issue fetching data
    builder.addCase(fetchData.rejected, (state, action) => {
      state.status = 'failed';
      state.error = action.error.message;
    });

    // Handle the pending state while saving data
    builder.addCase(saveData.pending, (state) => {
      state.status = 'loading';
    });

    // Handle the success state after successfully saving data
    builder.addCase(saveData.fulfilled, (state, action) => {
      state.status = 'succeeded';
      state.data.push(action.payload); // Assuming the saved data is returned by the server
    });

    // Handle the error state if there's an issue saving data
    builder.addCase(saveData.rejected, (state, action) => {
      state.status = 'failed';
      state.error = action.error.message;
    });
  },
});

// Export the async thunks for external use
export { fetchData, saveData };

// Export the reducer
export default comparableDataSlice.reducer;
```

