            <label>Header:</label>
            <input
              type="text"
              value={parameter.header}
              onChange={(e) =>
                handleParameterChange(index, "header", e.target.value)
              }
            /> <br/>
            <label>Value:</label>
            <input
              type="text"
              value={parameter.value}
              onChange={(e) =>
                handleParameterChange(index, "value", e.target.value)
              }
            /> <br/>
            <CustomButton onClick={() => handleRemoveParameter(index)}>
              Remove Parameter
            </CustomButton>
          </div>
        ))}
