// comparableDataSlice.js
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import axios from 'axios';

// Define the initial state
const initialState = {
  data: [],
  status: 'idle', // 'idle', 'loading', 'succeeded', 'failed'
  error: null,
};

// Define an async thunk for fetching data
export const fetchData = createAsyncThunk('comparableData/fetchData', async () => {
  try {
    const response = await axios.get('/api/comparableData');
    return response.data;
  } catch (error) {
    throw error;
  }
});

// Define an async thunk for saving data
export const saveData = createAsyncThunk('comparableData/saveData', async (dataToSave) => {
  try {
    const response = await axios.post('/api/comparableData', dataToSave);
    return response.data;
  } catch (error) {
    throw error;
  }
});

// Define an async thunk for updating data
export const updateData = createAsyncThunk('comparableData/updateData', async ({ id, updatedData }) => {
  try {
    const response = await axios.put(`/api/comparableData/${id}`, updatedData);
    return response.data;
  } catch (error) {
    throw error;
  }
});

// Define the slice
