const SaveUpdateComparableData = ({ dataToEdit, onSaveComplete }) => {
  const dispatch = useDispatch();
  const [formData, setFormData] = useState({
    _id: dataToEdit?._id || '',
    title: dataToEdit?.title || '',
    initialSummary: dataToEdit?.initialSummary || '',
