public class PresignedUrlUploadStringExample {
    public static void main(String[] args) throws IOException {
        String presignedUrlString = "YOUR_PRESIGNED_URL"; // Replace with your actual presigned URL
        String textToUpload = "This is the text that you want to upload to the S3 file.";

        URL presignedUrl = new URL(presignedUrlString);
        HttpURLConnection connection = (HttpURLConnection) presignedUrl.openConnection();

        connection.setRequestMethod("PUT");
        connection.setDoOutput(true);

        connection.setRequestProperty("Content-Type", "text/plain"); // Set the Content-Type header

        try (InputStream inputStream = new ByteArrayInputStream(textToUpload.getBytes())) {
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                connection.getOutputStream().write(buffer, 0, bytesRead);
            }
        }

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            System.out.println("String text uploaded successfully!");
        } else {
            System.out.println("Failed to upload string text. Response code: " + responseCode);
        }

        connection.disconnect();
    }
}
```

