        String fileName = "example.txt"; // Replace with your file name

        URL presignedUrl = new URL(presignedUrlString);
        HttpURLConnection connection = (HttpURLConnection) presignedUrl.openConnection();

        connection.setRequestMethod("PUT");
        connection.setDoOutput(true);

        // Determine content type based on file extension
        String contentType = URLConnection.guessContentTypeFromName(fileName);
        if (contentType == null) {
            contentType = "application/octet-stream"; // Default to binary data if content type cannot be determined
        }

        connection.setRequestProperty("Content-Type", contentType);

        try (InputStream inputStream = new ByteArrayInputStream(textToUpload.getBytes())) {
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                connection.getOutputStream().write(buffer, 0, bytesRead);
            }
