import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.web.reactive.function.BodyInserters;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.core.publisher.Mono;

@Service
public class ResumeService {

    private static final String GRAPHQL_ENDPOINT = "http://localhost:3000/graphql";

    private final WebClient webClient;

    @Autowired
    public ResumeService(WebClient.Builder webClientBuilder) {
        this.webClient = webClientBuilder.baseUrl(GRAPHQL_ENDPOINT).build();
    }

    public Resume getResume(int id) {
        String query = "{ getResume(id: " + id + ") { id, name, title, experience, skills } }";
        String requestJson = "{\"query\": \"" + query + "\"}";

        return webClient.post()
