function buildHierarchy(nodes) {
    // Create a map to quickly access nodes by their uniqueId
    const nodeMap = new Map();
    nodes.forEach(node => nodeMap.set(node.uniqueId, node));

    // Initialize an array to hold the root nodes (nodes with no parent)
    const rootNodes = [];

    // Iterate over the nodes to build the hierarchy
    nodes.forEach(node => {
        // If node has a parentId, add it to the parent's children array
        if (node.parentId) {
            const parent = nodeMap.get(node.parentId);
            if (parent) {
                parent.children = parent.children || [];
                parent.children.push(node);
            }
        } else {
            // If node has no parentId, it is a root node
            rootNodes.push(node);
        }
    });

    return rootNodes;
}

module.exports= buildHierarchy;


function fillParentIds(nodes) {
    const stack = [];
    const nodeMap = new Map();

    // Create a map of nodeId to node for quick lookup
    nodes.forEach(node => nodeMap.set(node.uniqueId, node));

    for (let i = 0; i < nodes.length; i++) {
        const node = nodes[i];

        // Maintain stack based on the level
        while (stack.length && stack[stack.length - 1].level >= node.level) {
            stack.pop();
        }

        // Assign parentId based on the stack
        node.parentId = stack.length ? stack[stack.length - 1].uniqueId : '';

        // Push the current node onto the stack
        stack.push(node);
    }

    return nodes;
}

