const ErrorCodes= require('./error-codes');

function validate(lines) {
    if (lines.length === 0) {
        return {
            isValid: true,
            errorCode: ErrorCodes.SUCCESS.code,
            message: ErrorCodes.SUCCESS.message,
            data: []
        };
    }

    const indentationLevel = (line) => line.search(/\S/);

    if (lines.length === 1) {
        return {
            isValid: true,
            errorCode: ErrorCodes.SUCCESS.code,
            message: ErrorCodes.SUCCESS.message,
            data: [{ name: lines[0].trim(), level: 0, children: [] }]
        };
    }

    const firstIndentation = indentationLevel(lines[0]);
    const levels = lines.map(line => indentationLevel(line));
    const uniqueLevels = Array.from(new Set(levels));

    if (uniqueLevels.length === 1) {
        return {
            isValid: true,
            errorCode: ErrorCodes.SUCCESS.code,
            message: ErrorCodes.SUCCESS.message,
            data: lines.map(line => ({ name: line.trim(), level: 0, children: [] }))
        };
    }

    const firstDifference = uniqueLevels[1] - uniqueLevels[0];

    for (let i = 1; i < uniqueLevels.length; i++) {
        const diff = uniqueLevels[i] - uniqueLevels[i - 1];
        if (diff !== firstDifference && diff % firstDifference !== 0) {
            return {
                isValid: false,
                errorCode: ErrorCodes.INCONSISTENT_INDENTATION.code,
                message: ErrorCodes.INCONSISTENT_INDENTATION.message,
                data: []
            };
        }
    }

    const result = [];
    const stack = [{ name: lines[0].trim(), level: 0, children: [] }];
    result.push(stack[0]);

    for (let i = 1; i < lines.length; i++) {
        const level = (indentationLevel(lines[i]) - firstIndentation) / firstDifference;
        const node = { name: lines[i].trim(), level, children: [] };

        while (stack.length > 0 && stack[stack.length - 1].level >= level) {
            stack.pop();
        }

        if (stack.length > 0) {
            stack[stack.length - 1].children.push(node);
        }

        stack.push(node);
        result.push(node);
    }

    return {
        isValid: true,
        errorCode: ErrorCodes.SUCCESS.code,
        message: ErrorCodes.SUCCESS.message,
        data: result
    };
}


module.exports= validate;

