import java.util.*;

class Node {
    String id;
    String value;
    List<Edge> edges;

    public Node(String id, String value) {
        this.id = id;
        this.value = value;
        this.edges = new ArrayList<>();
    }
}

class Edge {
    String from;
    String to;
    String relation;

    public Edge(String from, String to, String relation) {
        this.from = from;
        this.to = to;
        this.relation = relation;
    }
}

class Graph {
    Map<String, Node> nodes;

    public Graph() {
        this.nodes = new HashMap<>();
    }

    public void addNode(String id, String value) {
        nodes.put(id, new Node(id, value));
    }

    public void addEdge(String from, String to, String relation) {
        Node fromNode = nodes.get(from);
        Node toNode = nodes.get(to);
        if (fromNode != null && toNode != null) {
            fromNode.edges.add(new Edge(from, to, relation));
        }
    }

    public Node getNode(String id) {
        return nodes.get(id);
    }
}
```

