```java
import com.mongodb.client.*;
import org.bson.Document;
import java.util.ArrayList;
import java.util.List;

public class GraphMongoDB {
    private static final String DATABASE_NAME = "graphDB";
    private static final String COLLECTION_NAME = "graph";

    private MongoClient mongoClient;
    private MongoDatabase database;
    private MongoCollection<Document> collection;

    public GraphMongoDB() {
        mongoClient = MongoClients.create("mongodb://localhost:27017");
        database = mongoClient.getDatabase(DATABASE_NAME);
        collection = database.getCollection(COLLECTION_NAME);
    }

    public void insertGraph(Graph graph) {
        for (Node node : graph.nodes.values()) {
            Document nodeDoc = new Document("id", node.id)
                    .append("value", node.value)
                    .append("edges", new ArrayList<Document>());

            for (Edge edge : node.edges) {
                Document edgeDoc = new Document("from", edge.from)
                        .append("to", edge.to)
                        .append("relation", edge.relation);
                nodeDoc.getList("edges", Document.class).add(edgeDoc);
            }

            collection.insertOne(nodeDoc);
        }
    }

    public Graph getGraph() {
        Graph graph = new Graph();
        FindIterable<Document> docs = collection.find();

