### Custom Hook: `useFetchData.js`

```javascript
import { useState, useEffect } from 'react';
import { fetchAllTasks } from '../common/utils/third-party-apis/fetch-all-tasks';
import {
    generateTreeData,
    getUpdatedArrayForType,
} from '../common/utils/object-and-array-operation-utils';

const useFetchData = (configurations) => {
    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true);
            try {
                if (configurations.arraySourceMode === "ArrayType") {
                    setData(
                        configurations.selectedArrayType
                            ? await getUpdatedArrayForType(configurations.selectedArrayType)
                            : []
                    );
                } else if (configurations.arraySourceMode === "GENERATED_TREE_DATA") {
                    setData(
                        await generateTreeData(configurations.treeDepth, configurations.itemsPerLevel)
                    );
                } else if (configurations.arraySourceMode === "THIRD_PARTY_API_DATA") {
                    const result = await fetchAllTasks();
                    if (result.status === 'success') {
                        setData(result.data);
                    } else {
                        setError(result.error);
                    }
                }
            } catch (err) {
                setError(err);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, [configurations]);

    return { data, loading, error };
};

export default useFetchData;
```

