### React Component to Move Tree Nodes

This component demonstrates how to drag and drop nodes within a tree structure, moving nodes (along with their children) to different parent nodes. We will:
- Use unique IDs and parent IDs to manage the tree structure.
- Handle the drag and drop events.

```jsx
import React, { useState } from "react";

// Helper function to generate unique IDs and parent IDs
const generateUniqueIds = (node, parentId = null) => {
  const uniqueId = Math.random().toString(36).substr(2, 9);
  return {
    ...node,
    uniqueId,
    parentId,
    children: node.children.map((child) =>
      generateUniqueIds(child, uniqueId)
    ),
  };
};

// Sample treeData with uniqueId and parentId
const initialTreeData = [
  {
    name: "Root Node",
    children: [
      {
        name: "Child Node 1",
        children: [
          {
            name: "Grandchild Node 1.1",
            children: [],
          },
          {
            name: "Grandchild Node 1.2",
            children: [
              {
                name: "Great Grandchild Node 1.2.1",
                children: [],
              },
            ],
          },
        ],
      },
      {
        name: "Child Node 2",
        children: [
          {
            name: "Grandchild Node 2.1",
            children: [],
          },
        ],
      },
      {
        name: "Child Node 3",
        children: [],
      },
    ],
  },
].map(generateUniqueIds);

const TreeNode = ({ node, handleDragStart, handleDrop }) => {
  return (
    <div
      draggable
      onDragStart={(e) => handleDragStart(e, node)}
      onDragOver={(e) => e.preventDefault()} // Prevent default to allow dropping
      onDrop={(e) => handleDrop(e, node)}
      style={{
        paddingLeft: "20px",
        border: "1px solid gray",
        margin: "5px 0",
      }}
    >
      {node.name}
      {node.children && node.children.length > 0 && (
        <div style={{ paddingLeft: "10px" }}>
          {node.children.map((child) => (
            <TreeNode
              key={child.uniqueId}
              node={child}
              handleDragStart={handleDragStart}
              handleDrop={handleDrop}
            />
          ))}
        </div>
      )}
    </div>
  );
};

const Tree = () => {
  const [treeData, setTreeData] = useState(initialTreeData);
  const [draggedNode, setDraggedNode] = useState(null);

  const handleDragStart = (e, node) => {
    setDraggedNode(node);
  };

  const handleDrop = (e, targetNode) => {
    e.preventDefault();

    if (draggedNode && draggedNode.uniqueId !== targetNode.uniqueId) {
      // Avoid dropping on the dragged node or its children
      if (!isDescendant(draggedNode, targetNode)) {
        setTreeData((prevTreeData) => {
          let updatedTreeData = removeNode(prevTreeData, draggedNode.uniqueId);
          updatedTreeData = addNodeToParent(updatedTreeData, targetNode, draggedNode);
          return updatedTreeData;
        });
      }
    }
  };

  // Helper function to check if a node is a descendant of another
  const isDescendant = (node, targetNode) => {
    if (!node.children || node.children.length === 0) return false;
    return node.children.some(
      (child) =>
        child.uniqueId === targetNode.uniqueId ||
        isDescendant(child, targetNode)
    );
  };

  // Remove the dragged node from its current parent
  const removeNode = (nodes, nodeId) => {
    return nodes
      .map((node) => {
        if (node.uniqueId === nodeId) {
          return null; // Remove the node
        }

        return {
          ...node,
          children: removeNode(node.children, nodeId),
        };
      })
      .filter(Boolean); // Remove null entries
  };

  // Add the dragged node to the new parent
  const addNodeToParent = (nodes, targetNode, draggedNode) => {
    return nodes.map((node) => {
      if (node.uniqueId === targetNode.uniqueId) {
        return {
          ...node,
          children: [...node.children, { ...draggedNode, parentId: node.uniqueId }],
        };
      }

      return {
        ...node,
        children: addNodeToParent(node.children, targetNode, draggedNode),
      };
    });
  };

  return (
    <div>
      {treeData.map((node) => (
        <TreeNode
          key={node.uniqueId}
          node={node}
          handleDragStart={handleDragStart}
          handleDrop={handleDrop}
        />
      ))}
    </div>
  );
};

export default Tree;
```

### Key Features
1. **Unique ID and Parent ID**: The `generateUniqueIds` function adds a `uniqueId` and `parentId` to each node in the tree, helping us track nodes during drag and drop.

2. **Drag and Drop**:
   - **Drag**: The `handleDragStart` function captures the node being dragged.
   - **Drop**: The `handleDrop` function captures the target node (where the dragged node is dropped). It then:
     1. Removes the dragged node from its current parent.
     2. Adds the dragged node to the new target node's `children`.

3. **Prevent Invalid Drop**: We prevent dragging a node into one of its own descendants, which would result in an invalid tree structure.

4. **Recursive Operations**:
   - **Remove Node**: The `removeNode` function recursively searches for the node to be removed from its current parent.
   - **Add Node**: The `addNodeToParent` function recursively adds the dragged node as a child of the target node.

### How it works:
- Nodes can be dragged and dropped to new parents in the tree.
- The dragged node and its entire subtree move together.
- We prevent circular references by ensuring nodes cannot be dropped onto their own descendants.

