    if (lineArray.length === 0) {
        return { data: [], validInput: false, message: "Input has no valid lines" };
    } else if (lineArray.length === 1) {
        return {
            data: lineArray.map((line) => ({ ...line, level: 0 })),
            validInput: true,
            message: "Success",
        };
    }

    // Check for consistent indentation
    const firstLineIndentationLevel = lineArray[0].indentationLevel;
    const getFirstDifference= (arr)=>{
        let currentIndex=1;
        let prevIndex=0;
        let diff=arr[currentIndex].indentationLevel- firstLineIndentationLevel;
        while(diff==0 && currentIndex < arr.length){
            prevIndex=currentIndex+1;
        }
        return lineArray[1].indentationLevel- firstLineIndentationLevel;
    };
    const firstDifference=getFirstDifference(lineArray);
    let previousDifferenceOfIndentationLevel = firstDifference;
    for (let i = 2; i < lineArray.length; i++) {        
        if (previousDifferenceOfIndentationLevel<0) {
            return {
                data: [],
                validInput: false,
                message: `Inconsistent indentation at line: ${lineArray[i-1].name},
                 indentation of any line should not be less than firstLineIndentationLevel`,
            };
        }else if (previousDifferenceOfIndentationLevel) {
            return {
                data: [],
                validInput: false,
                message: `Inconsistent indentation at line: ${lineArray[i].name}`,
            };
        }
        previousDifferenceOfIndentationLevel = lineArray[i].indentationLevel;
    }
    for (let i = 1; i < lineArray.length; i++) {
        const currentLevel = lineArray[i].indentationLevel;
        if (currentLevel < previousLevel && currentLevel > previousLevel - 1) {
            return {
                data: [],
                validInput: false,
                message: `Inconsistent indentation at line: ${lineArray[i].name}`,
            };
        }
        previousLevel = currentLevel;
    }

    return { data: lineArray, validInput: true, message: "Success" };
};

