// TreeNode factory function
const createTreeNode = (name) => ({
    name,
    children: []
});

// Function to add a child node
const addChild = (node, childName) => {
    const childNode = createTreeNode(childName);
    return {
        ...node,
        children: [...node.children, childNode]
    };
};

// Function to add a sibling node
const addSibling = (parentNode, siblingName) => {
    const siblingNode = createTreeNode(siblingName);
    return {
        ...parentNode,
        children: [...parentNode.children, siblingNode]
    };
};

// Recursive function to find and update a node with a new child
const addChildRecursively = (node, targetName, childName) => {
    if (node.name === targetName) {
        return addChild(node, childName);
    }

    return {
        ...node,
        children: node.children.map(child =>
            addChildRecursively(child, targetName, childName)
        )
    };
};

// Recursive function to find and update a node with a new sibling
const addSiblingRecursively = (node, targetName, siblingName) => {
    return {
        ...node,
        children: node.children.map(child => {
            if (child.name === targetName) {
                return addSibling(node, siblingName);
            }
            return addSiblingRecursively(child, targetName, siblingName);
        })
    };
};

// Function to build the tree
const buildTree = () => {
    let tree = createTreeNode('World');

    tree = addChild(tree, 'Africa');
    tree = addChildRecursively(tree, 'Africa', 'Nigeria');
    tree = addChildRecursively(tree, 'Nigeria', 'Lagos');
    tree = addSiblingRecursively(tree, 'Lagos', 'Abuja');
    tree = addSiblingRecursively(tree, 'Abuja', 'Kano');

    tree = addSiblingRecursively(tree, 'Africa', 'Egypt');
    tree = addChildRecursively(tree, 'Egypt', 'Cairo');
    tree = addSiblingRecursively(tree, 'Cairo', 'Alexandria');
    tree = addSiblingRecursively(tree, 'Alexandria', 'Giza');

    tree = addSiblingRecursively(tree, 'Africa', 'South Africa');
    tree = addChildRecursively(tree, 'South Africa', 'Johannesburg');
    tree = addSiblingRecursively(tree, 'Johannesburg', 'Cape Town');
    tree = addSiblingRecursively(tree, 'Cape Town', 'Durban');

    tree = addSibling(tree, 'Asia');
    tree = addChildRecursively(tree, 'Asia', 'China');
    tree = addChildRecursively(tree, 'China', 'Beijing');
    tree = addSiblingRecursively(tree, 'Beijing', 'Shanghai');
    tree = addSiblingRecursively(tree, 'Shanghai', 'Shenzhen');

    tree = addSiblingRecursively(tree, 'Asia', 'India');
    tree = addChildRecursively(tree, 'India', 'Mumbai');
    tree = addSiblingRecursively(tree, 'Mumbai', 'Delhi');
    tree = addSiblingRecursively(tree, 'Delhi', 'Bangalore');

    tree = addSiblingRecursively(tree, 'Asia', 'Japan');
    tree = addChildRecursively(tree, 'Japan', 'Tokyo');
    tree = addSiblingRecursively(tree, 'Tokyo', 'Osaka');
    tree = addSiblingRecursively(tree, 'Osaka', 'Kyoto');

    return tree;
};

// Generate and print the tree
const tree = buildTree();
console.log(JSON.stringify(tree, null, 2));
```

### Explanation:
- **createTreeNode**: A factory function that creates a new tree node.
- **addChild**: Adds a child node to the given node.
- **addSibling**: Adds a sibling node to the given node's parent.
- **addChildRecursively**: Recursively searches for the node with the specified name and adds a child node.
- **addSiblingRecursively**: Recursively searches for the node with the specified name and adds a sibling node.
- **buildTree**: Uses the functions above to build the tree structure.

### Functional Characteristics:
- **Immutability**: Each function returns a new tree structure without modifying the original node.
- **Pure Functions**: Each function's output depends only on its input, making it easier to reason about the code.

