Here's a basic implementation of a Token Validation Middleware in Node.js using Express.js that validates JWT tokens for their signature and expiration:

```javascript
const jwt = require('jsonwebtoken');
const { JWT_SECRET } = require('./config'); // Import your JWT secret from configuration

function tokenValidationMiddleware(req, res, next) {
    // Extract token from request headers
    const token = req.headers.authorization;

    // Check if token is provided
    if (!token) {
        return res.status(401).json({ message: 'Authorization token is missing' });
    }

    try {
        // Verify JWT token
        const decoded = jwt.verify(token, JWT_SECRET);

        // Attach decoded token payload to request object for further processing
        req.user = decoded;

        // Check token expiration
        if (decoded.exp < Date.now() / 1000) {
            return res.status(401).json({ message: 'Authorization token has expired' });
        }

        // Token is valid, proceed to next middleware
        next();
    } catch (error) {
        // Token verification failed
        return res.status(401).json({ message: 'Invalid authorization token' });
    }
}

module.exports = tokenValidationMiddleware;
```

This middleware performs the following steps:

1. Extracts the JWT token from the `Authorization` header of the incoming request.
2. Verifies the token's signature using the provided JWT secret.
3. Checks if the token has expired by comparing the expiration time (`exp` claim) with the current time.
4. If the token is valid and not expired, it attaches the decoded token payload to the `req.user` object for further processing.
5. If the token is missing, invalid, or expired, it returns an appropriate HTTP error response.

You can use this middleware in your Express.js application by simply adding it to your routes where token validation is required. For example:

```javascript
const express = require('express');
const app = express();
const tokenValidationMiddleware = require('./tokenValidationMiddleware');

// Apply token validation middleware to specific routes
app.use('/api', tokenValidationMiddleware);

// Define your routes
app.get('/api/resource', (req, res) => {
    // Access user information from req.user
    const user = req.user;
    res.json({ message: 'Protected resource accessed successfully', user });
});

// Start the server
app.listen(3000, () => {
    console.log('Server is running on port 3000');
});
```

This middleware only validates the JWT token for its signature and expiration and can be used in your API gateway to enforce token-based session management.

