```javascript
const mongoose = require('mongoose');
const fs = require('fs');
const path = require('path');

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/mydatabase', { useNewUrlParser: true, useUnifiedTopology: true });
const db = mongoose.connection;
db.on('error', console.error.bind(console, 'MongoDB connection error:'));

// Define schema for roles
const roleSchema = new mongoose.Schema({
    roleName: String,
    roleDescription: String
});

const Role = mongoose.model('Role', roleSchema);

// Path to the JSON file
const jsonFilePath = path.join(__dirname, 'public', 'roles.json');

// Read the JSON file
fs.readFile(jsonFilePath, 'utf8', (err, data) => {
    if (err) {
        console.error('Error reading JSON file:', err);
        return;
    }

    try {
        const jsonData = JSON.parse(data);

        // Insert data into MongoDB
        Role.insertMany(jsonData.roles, (err, docs) => {
            if (err) {
                console.error('Error inserting data into MongoDB:', err);
            } else {
                console.log('Data inserted successfully:', docs);
            }
        });
    } catch (parseErr) {
        console.error('Error parsing JSON data:', parseErr);
    }
});
```

Make sure to replace `'mongodb://localhost:27017/mydatabase'` with the connection URL of your MongoDB database. Additionally, adjust the paths as necessary if your JSON file is located elsewhere.

