```javascript
const mongoose = require('mongoose');
const { Queue } = require('queue-typescript');

// Define the schema
const topicSchema = new mongoose.Schema({
    uniqueId: { type: String, unique: true },
    title: String,
    description: String,
    children: [String],
    parentId: { type: String, default: null }
});

// Define the model
const Topic = mongoose.model('Topic', topicSchema);

// Function to perform Breadth-First Search (BFS)
async function bfs(rootTopicId) {
    const queue = new Queue<string>();
    const visited = new Set<string>();

    queue.enqueue(rootTopicId);
    visited.add(rootTopicId);

    while (!queue.isEmpty()) {
        const currentId = queue.dequeue() as string;
        const topic = await Topic.findOne({ uniqueId: currentId });

        if (topic) {
            console.log(`Title: ${topic.title}, UniqueId: ${topic.uniqueId}`);

            if (topic.children && topic.children.length > 0) {
                for (const childId of topic.children) {
                    if (!visited.has(childId)) {
                        queue.enqueue(childId);
                        visited.add(childId);
                    }
                }
            }
        }
    }
}

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/your_database', { useNewUrlParser: true, useUnifiedTopology: true })
    .then(async () => {
        // Fetching the root topic
        const rootTopic = await Topic.findOne({ parentId: null });

        // Starting BFS traversal from the root topic
        if (rootTopic) {
            await bfs(rootTopic.uniqueId);
        } else {
            console.log("Root topic not found.");
        }
    })
    .catch(err => console.error('Error connecting to MongoDB:', err));
```

