const { Category, Question, Answer } = require("./InterviewMgmt.v2.model");

const saveDocument = async (document) => {
    try {
        await document.save();
        return document;
    } catch (err) {
        console.error(err);
        throw err;
    }
};

const createCategory = async (categoryData) => {
    const category = new Category({
        ...categoryData,
        smartContent: categoryData.smartContent || null,
        tags: categoryData.tags || [],
        createdDate: new Date(),
        updatedDate: new Date(),
    });
    return saveDocument(category);
};

const updateCategoryByUniqueId = async (uniqueId, categoryData) => {
    const category = await Category.findOne({ uniqueId });
    if (!category) throw new Error("Category not found");

    const { name, heading, smartContent, rating, parentId, tags, children } = categoryData;
    Object.assign(category, {
        name: name || category.name,
        heading: heading || category.heading,
        parentId: parentId || category.parentId,
        smartContent: smartContent || category.smartContent,
        tags: tags?.length >= 0 ? tags : category.tags,
        rating: rating >= 0 ? rating : category.rating,
        updatedDate: new Date(),
    });

    const updatedCategory = await saveDocument(category);

    if (children?.length) {
        await Category.updateMany(
            { uniqueId: { $in: children } },
            { parentId: updatedCategory.uniqueId }
        );
    }

    return updatedCategory;
};

const getAllCategories = async () => {
    const selectFields = {
        uniqueId: 1,
        name: 1,
        heading: 1,
        parentId: 1,
    };
    return await getCategories(null, selectFields);
};

const getAllAncestors = async (parentId, ancestors = []) => {
    if (!parentId) return ancestors;
    const category = await Category.findOne({ uniqueId: parentId });
    if (!category) return ancestors;

    ancestors.unshift({
        name: category.name,
        uniqueId: category.uniqueId,
        parentId: category.parentId,
    });
    return getAllAncestors(category.parentId, ancestors);
};

const getCategories = async (parentId, selectFields) => {
    const criteria = parentId
        ? { parentId, isPrivate: false }
        : { parentId: { $in: [null, undefined, ""] }, isPrivate: false };

    const categories = await Category.find(criteria).select(selectFields);

    return await Promise.all(categories.map(async (category) => {
        const children = await getCategories(category.uniqueId, selectFields);
        const ancestors = await getAllAncestors(category.parentId);
        const questions = await getQuestionsForCategories(category.uniqueId);

        return { ...category.toObject(), children, ancestors, questions };
    }));
};

const getCategoryByUniqueId = async (uniqueId) => {
    const selectFields = {
        uniqueId: 1,
        name: 1,
        heading: 1,
        parentId: 1,
        smartContent: 1,
        title: 1,
        rating: 1,
    };
    const category = await Category.findOne({ uniqueId }).select(selectFields);
    const children = await Category.find({ parentId: uniqueId });
    const questions = await getQuestionsForCategories(uniqueId);
    const ancestors = await getAllAncestors(category?.parentId);

    return {
        ...category.toObject(),
        children: children.map(child => ({ title: child.title, uniqueId: child.uniqueId })),
        ancestors,
        questions,
    };
};

