import { getDateAsMillisecondsString } from "../commonService";

const defaultPrefix = 'NODE_ID_';

/**
 * Adds unique IDs to a given list of nodes and their children, optionally overriding existing IDs.
 * @param {Object[]} nodes - The nodes to process.
 * @param {string} [prefix] - Prefix for the unique IDs.
 * @param {boolean} [overrideId=true] - Whether to override existing IDs.
 * @returns {Object[]} - The nodes with unique IDs added.
 */
export const addUniqueIdsToTree = (nodes = [], prefix = `${defaultPrefix}${getDateAsMillisecondsString()}`, overrideId = true) => {
    if (!Array.isArray(nodes) || nodes.length < 1) return [];

    let currentId = 1;

    const add = (node) => {
        if (overrideId || !node.uniqueId?.trim()) {
            node = { ...node, uniqueId: `${prefix}_${currentId++}` };
        }

        if (node.children) {
            node.children = node.children.map(add);
        }

        return node;
    };

    return nodes.map(add);
};
