const InterviewMgmtContext = createContext();

export const InterviewMgmtProvider = ({ children }) => {
  const dispatch = useDispatch();
  const selectedTreeNodeUID = useSelector(
    (state) => state.interviewMgmt.selectedTreeNodeUID
  );
  const data = useSelector((state) => state.interviewMgmt.data);



  useEffect(() => {
    dispatch(fetchCategoryTree());
  }, [dispatch]);

  const getCatTreeData = (treeArr = []) => {
    // console.log("[getCatTreeData]: getCatTreeData: " + (treeArr?.length || 0));
    if (!treeArr?.length > 0) return [];

    return treeArr.reduce((acc, c) => {
      const catItem = {
        id: c.uniqueId,
        name: c.heading,
        type: "category",
        children: [],
      };
      acc.push(catItem);

      // Recursive handling of child categories
      if (c.children && c.children.length > 0) {
        catItem.children = catItem.children.concat(getCatTreeData(c.children));
      }

      // Handling questions
      if (c.questions && c.questions.length > 0) {
        catItem.children = catItem.children.concat(
          c.questions.map((q) => ({
            id: q.uniqueId,
            name: q.heading,
            type: "question",
          }))
        );
      }

      return acc;
    }, []);
  };

  const getQIdMap = (treeArr = []) => {
    // console.log("[getQIdMap]: getQIdMap: " + (treeArr?.length || 0));
    if (!(treeArr?.length > 0)) return [];

    const resultArr = treeArr.flatMap((category) => {
      const questionsMap =
        category.questions?.map((question) => ({
          categoryUniqueId: category.uniqueId,
          questionUniqueId: question.uniqueId,
        })) || [];

      const childrenMap = category.children ? getQIdMap(category.children) : [];

      return [...questionsMap, ...childrenMap];
    });

    return resultArr;
  };

  const refreshCategoryTree = () => dispatch(fetchCategoryTree());

  const catTreeList = useMemo(() => getCatTreeData(data), [data]);

  const { prevItem: prevTreeNode, nextItem: nextTreeNode } = useFlatTreeData(
    catTreeList,
    selectedTreeNodeUID, "id"
  );

  const qIdMap = useMemo(() => getQIdMap(data), [data]);

  return (
    <InterviewMgmtContext.Provider
      value={{
        catTreeList,
        qIdMap,
        data,
        selectedTreeNodeUID,
        prevTreeNode,
        nextTreeNode,
        refreshCategoryTree,
      }}
    >
      {children}
    </InterviewMgmtContext.Provider>
  );
};

export const useInterviewMgmt = () => {
  return useContext(InterviewMgmtContext);
};

