import React, { useEffect, useRef, useState } from "react";
import { CKEditor } from "@ckeditor/ckeditor5-react";
import ClassicEditor from "@ckeditor/ckeditor5-build-classic";
import yaml from "js-yaml";
import CustomButton from "../CustomButton";
import MarkdownComponent from "../MarkdownComponent";

const availableOutputTypes = {
    HTML: "html",
    YAML: "yaml",
    MARKDOWN: "markdown",
    TEXT: "text",
    SKELETON: "skeleton",
};
const availableInputTypes = {
    textArea: "TextArea",
    ckEditor: "CKEditor",
};

const inputOutputMapping = {
    RAW_TEXT: {
        command: "SHOW_TEXT_AREA",
        textOutputType: availableOutputTypes.TEXT,
        textInputType: availableInputTypes.textArea,
    },
    HTML_OUTPUT_FROM_RAW_TEXT: {
        command: "SHOW_TEXT_AREA",
        textOutputType: availableOutputTypes.HTML,
        textInputType: availableInputTypes.textArea,
    },
    HTML_OUTPUT_FROM_CKEDITOR: {
        command: "SHOW_CKEDITOR",
        textOutputType: availableOutputTypes.HTML,
        textInputType: availableInputTypes.ckEditor,
    },
    YAML: {
        command: "SHOW_TEXT_AREA",
        textOutputType: availableOutputTypes.YAML,
        textInputType: availableInputTypes.textArea,
    },
    MARKDOWN: {
        command: "SHOW_TEXT_AREA",
        textOutputType: availableOutputTypes.MARKDOWN,
        textInputType: availableInputTypes.textArea,
    },
    SKELETON: {
        command: "SHOW_TEXT_AREA",
        textOutputType: availableOutputTypes.SKELETON,
        textInputType: availableInputTypes.textArea,
    },
};

const getKeyName = (textOutputType, textInputType) => {
    if (!textOutputType || !textInputType) {
        return null;
    }
    let resultKey = null;
    Object.keys(inputOutputMapping).forEach((key) => {
        if (
            inputOutputMapping[key].textOutputType === textOutputType &&
            inputOutputMapping[key].textInputType === textInputType
        ) {
            resultKey = key;
        }
    });
    return resultKey;
};

const SmartEditor = ({
    initialValue,
    preview: previewIntialValue = true,
    onChange = () => { },
    onError = () => { },
}) => {
    const textareaRef = useRef(null);

    const [selectedOutputType, setSelectedOutputType] = useState(
        getKeyName(initialValue?.textOutputType, initialValue?.textInputType) ||
        "HTML_OUTPUT_FROM_RAW_TEXT"
    );
    const [showPreview, setShowPreview] = useState(previewIntialValue);

    const [formData, setFormData] = useState({
        content: initialValue?.content || "",
        textOutputType:
            initialValue?.textOutputType ||
            inputOutputMapping["HTML_OUTPUT_FROM_RAW_TEXT"].textOutputType,
        textInputType:
            initialValue?.textInputType ||
            inputOutputMapping["HTML_OUTPUT_FROM_RAW_TEXT"].textInputType,
    });

    const [yamlProcessedData, setYamlProcessedData] = useState(null);
    const [errorMessage, setErrorMessage] = useState("");

    useEffect(() => {
        setFormData((prev) => ({
            ...prev,
            textInputType: inputOutputMapping[selectedOutputType].textInputType,
            textOutputType: inputOutputMapping[selectedOutputType].textOutputType,
        }));
    }, [selectedOutputType]);

    useEffect(() => {
        if (
            formData.textOutputType === availableOutputTypes.YAML &&
            formData.content
        ) {
            try {
                const metadata = yaml.load(formData.content);
                setYamlProcessedData(metadata);
                setErrorMessage("");
            } catch (e) {
                const errorLine = e.mark ? e.mark.line + 1 : null;
                const error = errorLine
                    ? `Error parsing YAML at line ${errorLine}: ${e.message}`
                    : `Error parsing YAML: ${e.message}`;
                setErrorMessage(error);
            }
        }

        if (
            formData.textInputType === availableInputTypes.textArea &&
            textareaRef.current
        ) {
            const textarea = textareaRef.current;
            textarea.style.height = "auto";
            textarea.style.height = textarea.scrollHeight * 1.3 + "px";
        }

        onChange(formData);
    }, [formData]);

    const handleChangeOutputTypes = (event) => {
        console.log(`outputType selected: ${event.target.value}`);
        setSelectedOutputType(event.target.value);
    };

    const handleInputChange = (e) => {
        const { value } = e.target;
        setFormData((prev) => ({
            ...prev,
            content: value,
        }));
    };

    const handleEditorChange = (event, editor) => {
        const data = editor.getData();
        setFormData((prev) => ({
            ...prev,
            content: data,
        }));
    };

    return (
        <div>
            <label htmlFor="outputType" style={labelStyle}>
                Select Output Type:
            </label>
            <select value={selectedOutputType} onChange={handleChangeOutputTypes}>
                {Object.keys(inputOutputMapping).map((outputType) => (
                    <option key={outputType} value={outputType}>
                        {outputType.replaceAll("_", " ")}
                    </option>
                ))}
            </select>

            {formData.textInputType === availableInputTypes.textArea && (
                <div>
                    <label htmlFor="content" style={labelStyle}>
                        Content:
                    </label>
                    <br />
                    <textarea
                        ref={textareaRef}
                        id="content"
                        name="content"
                        value={formData.content}
                        onChange={handleInputChange}
                        style={styles.textarea}
                    />
                </div>
            )}

            {formData.textInputType === availableInputTypes.ckEditor && (
                <div>
                    <label htmlFor="ckeditor" style={labelStyle}>
                        Content:
                    </label>
                    <CKEditor
                        id="ckeditor"
                        name="content"
                        editor={ClassicEditor}
                        data={formData.content}
                        onChange={handleEditorChange}
                    />
                </div>
            )}

            {formData.content && (
                <div>
                    <b>Preview:</b>{" "}
                    <CustomButton onClick={() => setShowPreview((prev) => !prev)}>
                        {showPreview ? "Hide" : "Show"}
                    </CustomButton>
                </div>
            )}

            {showPreview && <SmartPreviewer data={formData} />}
        </div>
    );
};

const labelStyle = {
    fontWeight: "bold",
};

const styles = {
    textarea: {
        width: "100%",
        padding: "10px",
        fontSize: "16px",
        borderRadius: "4px",
        border: "1px solid #ccc",
        resize: "none",
        overflow: "hidden",
    },
};

const SmartPreviewer = ({ data }) => {
    const { content, textOutputType } = data;

    switch (textOutputType) {
        case availableOutputTypes.TEXT:
            return <pre>{content}</pre>;
        case availableOutputTypes.HTML:
            return <div dangerouslySetInnerHTML={{ __html: content }} />;
        case availableOutputTypes.MARKDOWN:
            return <MarkdownComponent markdownText={content} />;
        case availableOutputTypes.YAML:
            return (
                <div>
                    <pre>{yaml.dump(yaml.load(content))}</pre>
                </div>
            );
        case availableOutputTypes.SKELETON:
            return <pre>{content}</pre>;
        default:
            return null;
    }
};

export { SmartEditor };

