import { useMemo } from "react";

// Utility function to generate a flat array from tree data
const prepareFlatQueueFromTree = (list, prevQueue = []) => {
  let queue = [...prevQueue];
  if (list && list.length > 0) {
    list.forEach((t) => {
      queue = [
        ...queue,
        {
          uniqueId: t.uniqueId,
          name: t.name,
          title: getNameWithAncestors(t),
          ancestors: t.ancestors,
          children: t.children,
          _id: t._id,
        },
      ];
      const childQ = prepareFlatQueueFromTree(t.children, []);
      queue = [...queue, ...childQ];
    });
  }
  return queue;
};

// Utility function to get the fully qualified name with ancestors
const getNameWithAncestors = (task) => {
  if (!task) {
    return "";
  }
  let ancestorNames = [];
  let currentAncestor =
    task.ancestors?.find((ancestor) => !ancestor.parentId) || null;
  while (currentAncestor) {
    ancestorNames.push(currentAncestor.name);
    currentAncestor = task.ancestors.find(
      (ancestor) => ancestor.parentId === currentAncestor.uniqueId
    );
  }
  ancestorNames.push(task.name);
  const fullyQualifiedName = ancestorNames.join(" / ");
  return fullyQualifiedName;
};

const useTaskData = (treeData, selectedItemUniqueId) => {
  // Generate flat data from tree data
  const flatData = useMemo(() => prepareFlatQueueFromTree(treeData), [treeData]);

  // Get previous and next task uniqueId
  const prevItemUniqueId = useMemo(() => {
    const dataLength = flatData?.length || 0;
    const selectedIndex = flatData.findIndex(
      (task) => task.uniqueId === selectedItemUniqueId
    );
    if (selectedIndex < 0) {
      return null;
    }
    const prevIndex = (selectedIndex + dataLength - 1) % dataLength;
    return flatData[prevIndex]?.uniqueId || null;
  }, [flatData, selectedItemUniqueId]);

  const nextItemUniqueId = useMemo(() => {
    const dataLength = flatData?.length || 0;
    const selectedIndex = flatData.findIndex(
      (task) => task.uniqueId === selectedItemUniqueId
    );
    if (selectedIndex < 0) {
      return null;
    }
    const nextIndex = (selectedIndex + dataLength + 1) % dataLength;
    return flatData[nextIndex]?.uniqueId || null;
  }, [flatData, selectedItemUniqueId]);

  return {
    flatData,
    prevItemUniqueId,
    nextItemUniqueId,
  };
};

export default useTaskData;

