const SmartPreviewer = ({ data }) => {
    const { content, textOutputType } = data;

    const [yamlProcessedData, setYamlProcessedData] = useState(null);
    const [errorMessage, setErrorMessage] = useState("");
    const [resultData, setResultData] = useState([]);

    useEffect(() => {
        // This effect will run only when formData.content changes
        // console.log("formData.content changed:", formData.content);
        // Add your logic here that should run when formData.content changes
        if (
            content &&
            textOutputType === availableOutputTypes.YAML
        ) {
            let metadata = {};
            let error = "";
            try {
                metadata = yaml.load(content);
            } catch (e) {
                if (e.mark) {
                    // If the error has 'mark' property, it contains line and column information
                    const errorLine = e.mark.line + 1; // Adjust for 0-based index
                    error = `Error parsing YAML at line ${errorLine}: ${e.message}`;
                } else {
                    // If the error does not have 'mark' property, it's a general parsing error
                    error = `Error parsing YAML: ${e.message}`;
                }
            }
            setYamlProcessedData(metadata);
            setErrorMessage(error);
        }
        if (textOutputType === availableOutputTypes.SKELETON && content) {
            const { data:skeletonData,isValid, message } = buildTree(content);
            if(!isValid){
                setErrorMessage(message);
            }else{
                setResultData(()=>[...skeletonData])
            }
        }
    }, [content]);

    switch (textOutputType) {
        case availableOutputTypes.TEXT:        
            return <pre>{content}</pre>;
        case availableOutputTypes.HTML:
            return <div dangerouslySetInnerHTML={{ __html: content }} />;
        case availableOutputTypes.MARKDOWN:
            return <MarkdownComponent markdownText={content} />;
        case availableOutputTypes.YAML:
            return (
                <div>
                    <pre>{JSON.stringify(yamlProcessedData, null, 2) || ""}</pre>
                    <span style={{ color: "red" }}>{errorMessage}</span>
                </div>
            );
        case availableOutputTypes.SKELETON:
            return <>
            <Tree data={resultData} />
            <span style={{ color: "red" }}>{errorMessage}</span>
            </>
        default:
            return null;
    }
};

