import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import Select from "react-select";
import CustomButton from "../../../common/components/CustomButton";
import RatingComponent from "../../../common/components/RatingComponent";
import { SmartEditor } from "../../../common/components/SmartEditor";
import {
  createCategory,
  updateCategory,
} from "../../../redux/slices/interviewMgmtSlice";
import { fetchTags, selectAllFlatTags } from "../../../redux/slices/tagsSlice";
import JSONDataViewer from "../../../common/components/JSONDataViewer";

const CategoryForm = ({ parentId, category, onSave, onCancelEdit }) => {
  const dispatch = useDispatch();
  const availableTags = useSelector(selectAllFlatTags);
  const { createCategoryResponse, updateCategoryResponse } = useSelector(
    (state) => state.interviewMgmt
  );

  const [formData, setFormData] = useState({
    name: category ? category.name : "",
    heading: category ? category.heading : "",
    linkedCategoryId: category ? category.linkedCategoryId : "",
    smartContent: category?.smartContent || {
      content: "",
      textOutputType: "",
      textInputType: "",
    },
    parentId: parentId ? parentId : "",
    rating: category?.rating || 0,
    tags: category?.tags || [],
  });

  const [formErrors, setFormErrors] = useState([]);
  const [smartEditorError, setSmartEditorError] = useState(null);

  useEffect(() => {
    if (createCategoryResponse.error || updateCategoryResponse.error) {
      setFormErrors((prev) => [
        createCategoryResponse.error ||
        updateCategoryResponse.error ||
        "Missing error message: Please contact administrator",
      ]);
    }
  }, [createCategoryResponse, updateCategoryResponse]);

  useEffect(() => {
    dispatch(fetchTags());
  }, [dispatch]);

  const validateForm = () => {
    const errors = [];

    if (!formData.name.trim()) {
      errors.push("Name is required");
    }

    if (!formData.heading.trim()) {
      errors.push("Heading is required");
    }

    if (formData.rating <= 0) {
      errors.push("Rating is required, it should have non-zero value");
    }

    if (smartEditorError) {
      errors.push(smartEditorError);
    }

    setFormErrors(errors);

    return Object.keys(errors).length === 0;
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleTagSelect = (selectedTags) => {
    // Extract the tag values and store them in the 'tags' property of the category data
    setFormData({ ...formData, tags: selectedTags.map((tag) => tag.value) });
  };

  const tagOptions = availableTags.map((tag) => ({
    value: tag.uniqueId, // Assuming tags have unique IDs
    label: tag.title, // Display tag names in the dropdown
  }));

  const handleSaveCategory = (event) => {
    event.preventDefault();
    if (!validateForm()) {
      return;
    }
    if (category && category.uniqueId) {
      // If a category is provided, it's an update
      dispatch(updateCategory({ ...formData, uniqueId: category.uniqueId }));
    } else {
      // Otherwise, it's a new category creation
      dispatch(createCategory(formData));
    }

    // Notify the parent component to handle closing the CreateCategory form
    if (onSave) {
      onSave();
    }
  };

  const handleSmartEditorChange = (smartContent) => {
    setFormData({ ...formData, smartContent: smartContent });
  };

  const handleSmartEditorError = (error) => {
    setSmartEditorError(error);
  };

  const formStyle = {};

  return (
    <div style={formStyle}>
      <h3>
        {category && category.uniqueId ? "Edit Category" : "Add Category"}
      </h3>
      <div style={{ display: "flex", alignItems: "center", padding: "10px" }}>
        <label htmlFor="name" style={{ width: "9%", fontWeight: "bold" }}>
          Name:
        </label>
        <input
          type="text"
          id="name"
          name="name"
          value={formData.name}
          onChange={handleInputChange}
          style={{ width: "90%" }}
        />
      </div>
      <div style={{ display: "flex", alignItems: "center", padding: "10px" }}>
        <label htmlFor="name" style={{ width: "9%", fontWeight: "bold" }}>
          Heading:
        </label>
        <input
          type="text"
          id="heading"
          name="heading"
          value={formData.heading}
          onChange={handleInputChange}
          style={{ width: "90%" }}
        />
      </div>
      <div style={{ display: "flex", alignItems: "center", padding: "10px" }}>
        <label htmlFor="rating" style={{ width: "9%", fontWeight: "bold" }}>
          Rating:
        </label>
        <RatingComponent
          id="rating"
          rating={formData.rating}
          editable={true}
          onEdit={(editedValue) => {
            setFormData((prev) => ({ ...prev, rating: editedValue }));
          }}
        />
      </div>
      <div>
        <label htmlFor="description">Description:</label>
        <div
          style={{ border: "1px solid #ddd", padding: "5px", margin: "5px" }}
        >
          <SmartEditor
            initialValue={formData.smartContent}
            onChange={handleSmartEditorChange}
            onError={handleSmartEditorError}
          />
        </div>
      </div>

      <div>
        <label htmlFor="tags">Add Tags:</label>
        <Select
          isMulti
          name="tags"
          options={tagOptions}
          value={tagOptions.filter((tag) => formData.tags?.includes(tag.value))}
          onChange={handleTagSelect}
        />
      </div>
      <div>
        {formErrors.length > 0 && (
          <div>
            {formErrors.map((error, index) => (
              <span key={index} style={styles.error}>
                {error}
              </span>
            ))}
          </div>
        )}
      </div>
      <div>
        <JSONDataViewer
          metadata={{
            formData,
            createCategoryResponse,
            updateCategoryResponse,
          }}
          title="All collated Responses"
        />

        <CustomButton onClick={(event) => handleSaveCategory(event)}>
          {category ? "Update Changes" : "Save Changes"}
        </CustomButton>
        <CustomButton onClick={() => onCancelEdit()}>Cancel</CustomButton>
      </div>
    </div>
  );
};

const styles = {
  error: {
    color: "red",
    fontSize: "14px",
    marginTop: "5px",
    display: "block",
  },
  labelStyle: {
    width: "15%", // Set label width to 25%
    fontWeight: "bold", // Make label text bold
  },
  pairedComponentStyle: {
    width: "85%", // Set paired component width to 75%
  },
};

export default CategoryForm;

