```javascript
const mongoose = require('mongoose');
const { Category } = require('./models/Category'); // Adjust path as necessary
const { Tag } = require('./models/Tag'); // Adjust path as necessary

async function createTagCategoryMapping() {
    const categories = await Category.find().exec();
    const tagCategoryMapping = {};

    for (const category of categories) {
        // Assuming a tag with the same name as the category exists
        const tag = await Tag.findOne({ name: category.name }).exec();
        if (tag) {
            tagCategoryMapping[category.uniqueId] = tag.uniqueId;
        }
    }

    return tagCategoryMapping;
}

module.exports = { createTagCategoryMapping };
```

#### 3. Update Questions Script
```javascript
const mongoose = require('mongoose');
const { Question } = require('./models/Question'); // Adjust path as necessary
const { createTagCategoryMapping } = require('./utils/tagCategoryMapping'); // Adjust path as necessary

async function updateQuestionTags() {
    const tagCategoryMapping = await createTagCategoryMapping();

    const questions = await Question.find().exec();

    for (const question of questions) {
        const tagId = tagCategoryMapping[question.linkedCategoryId];
        if (tagId) {
            question.tags = [tagId];
            await question.save();
        }
    }
}

module.exports = { updateQuestionTags };
```

