const inputOutputMapping = {
    RAW_TEXT: "SHOW_TEXT_AREA",
    HTML_OUTPUT_FROM_RAW_TEXT: "SHOW_TEXT_AREA",
    HTML_OUTPUT_FROM_CKEDITOR: "SHOW_CKEDITOR",
    YAML: "SHOW_TEXT_AREA",
    MARKDOWN: "SHOW_TEXT_AREA",
    SKELETON: "SHOW_TEXT_AREA",
};

const SmartEditor = ({ initialValue, preview: previewIntialValue = true, onChange = () => { }, onError = () => { } }) => {
    const textareaRef = useRef(null);

    const [selectedOutputType, setSelectedOutputType] = useState("HTML_OUTPUT_FROM_RAW_TEXT");
    const [showPreview, setShowPreview] = useState(previewIntialValue);

    const [formData, setFormData] = useState({
        content: initialValue?.content || "",
        textOutputType: initialValue?.textOutputType || "HTML_OUTPUT_FROM_RAW_TEXT",
        textInputType: inputOutputMapping[initialValue?.textOutputType || "HTML_OUTPUT_FROM_RAW_TEXT"],
    });

    const [yamlProcessedData, setYamlProcessedData] = useState(null);
    const [errorMessage, setErrorMessage] = useState("");

    useEffect(() => {
        setFormData((prev) => ({
            ...prev,
            textInputType: inputOutputMapping[selectedOutputType],
            textOutputType: selectedOutputType,
        }));
    }, [selectedOutputType]);

    useEffect(() => {
        if (formData.textOutputType === "YAML" && formData.content) {
            try {
                const metadata = yaml.load(formData.content);
                setYamlProcessedData(metadata);
                setErrorMessage("");
            } catch (e) {
                const errorLine = e.mark ? e.mark.line + 1 : null;
                const error = errorLine
                    ? `Error parsing YAML at line ${errorLine}: ${e.message}`
                    : `Error parsing YAML: ${e.message}`;
                setErrorMessage(error);
