import React, { createContext, useContext, useEffect, useMemo } from "react";
import { useDispatch, useSelector } from "react-redux";
import { fetchCategoryTree } from "../../../redux/slices/interviewMgmtSlice";
import useFlatTreeData from "../../../common/hooks/useFlatTreeData";

const InterviewMgmtContext = createContext();

export const InterviewMgmtProvider = ({ children }) => {
  const dispatch = useDispatch();
  const selectedTreeNodeUID = useSelector(
    (state) => state.interviewMgmt.selectedTreeNodeUID
  );
  const data = useSelector((state) => state.interviewMgmt.data);

  useEffect(() => {
    dispatch(fetchCategoryTree());
  }, [dispatch]);

  const buildCategoryTree = (treeArr = []) => {
    if (!treeArr?.length) return [];

    return treeArr.reduce((acc, category) => {
      const categoryNode = {
        id: category.uniqueId,
        name: category.heading,
        type: "category",
        children: [],
      };
      acc.push(categoryNode);

      // Recursive handling of child categories
      if (category.children && category.children.length > 0) {
        categoryNode.children = categoryNode.children.concat(
          buildCategoryTree(category.children)
        );
      }

      // Handling questions
      if (category.questions && category.questions.length > 0) {
        categoryNode.children = categoryNode.children.concat(
          category.questions.map((question) => ({
            id: question.uniqueId,
            name: question.heading,
            type: "question",
          }))
        );
      }

      return acc;
    }, []);
  };

  const buildQuestionIdMap = (treeArr = []) => {
    if (!treeArr?.length) return [];

    return treeArr.flatMap((category) => {
      const questionsMap =
        category.questions?.map((question) => ({
          categoryUniqueId: category.uniqueId,
          questionUniqueId: question.uniqueId,
        })) || [];

      const childrenMap = category.children
        ? buildQuestionIdMap(category.children)
        : [];

      return [...questionsMap, ...childrenMap];
    });
  };

  const refreshCategoryTree = () => dispatch(fetchCategoryTree());

  const categoryTree = useMemo(() => buildCategoryTree(data), [data]);

  const { prevItem: prevTreeNode, nextItem: nextTreeNode } = useFlatTreeData(
    categoryTree,
    selectedTreeNodeUID,
    "id"
  );

  const questionIdMap = useMemo(() => buildQuestionIdMap(data), [data]);

  return (
    <InterviewMgmtContext.Provider
      value={{
        categoryTree,
        questionIdMap,
        data,
        selectedTreeNodeUID,
        prevTreeNode,
        nextTreeNode,
        refreshCategoryTree,
      }}
    >
      {children}
    </InterviewMgmtContext.Provider>
  );
};

export const useInterviewMgmt = () => {
  return useContext(InterviewMgmtContext);
};
```

### Changes Made:

1. **Function Names:**
   - Renamed `getCatTreeData` to `buildCategoryTree` for clarity.
   - Renamed `getQIdMap` to `buildQuestionIdMap` for better understanding of the function’s purpose.

2. **Conditional Checks:**
   - Simplified the conditions checking for array length in `buildCategoryTree` and `buildQuestionIdMap`.

3. **Variables:**
   - Renamed variables for consistency:
     - `catTreeList` to `categoryTree`.
     - `qIdMap` to `questionIdMap`.

4. **Use `useMemo`:**
   - Memoized `categoryTree` and `questionIdMap` to ensure they are only recalculated when `data` changes.

These changes ensure that variable and function names are standardized and meaningful, making the code easier to understand and maintain.

