       res.send('Hello World!');
     });

     app.listen(port, () => {
       console.log(`Example app listening at http://localhost:${port}`);
     });
     ```

2. **Lodash**:
   - A modern JavaScript utility library delivering modularity, performance, and extras.
   - Provides utility functions for common programming tasks like manipulating arrays, objects, strings, etc.
   - **Installation**:
     ```bash
     npm install lodash
     ```
   - **Basic Usage**:
     ```javascript
     const _ = require('lodash');

     const array = [1, 2, 3, 4];
     console.log(_.reverse(array)); // [4, 3, 2, 1]
     ```

3. **Axios**:
   - A promise-based HTTP client for the browser and Node.js.
   - Makes HTTP requests from node.js and XMLHttpRequests from the browser.
   - **Installation**:
     ```bash
     npm install axios
     ```
   - **Basic Usage**:
     ```javascript
     const axios = require('axios');

     axios.get('https://jsonplaceholder.typicode.com/todos/1')
       .then(response => {
         console.log(response.data);
       })
       .catch(error => {
         console.error('Error fetching data:', error);
       });
     ```

4. **jsonwebtoken**:
   - An implementation of JSON Web Tokens for authentication and information exchange.
   - **Installation**:
     ```bash
     npm install jsonwebtoken
     ```
   - **Basic Usage**:
     ```javascript
     const jwt = require('jsonwebtoken');
     const secretKey = 'your-256-bit-secret';

     const token = jwt.sign({ userId: 123 }, secretKey, { expiresIn: '1h' });
     console.log('Generated Token:', token);

     try {
       const decoded = jwt.verify(token, secretKey);
       console.log('Decoded Token:', decoded);
     } catch (err) {
       console.error('Invalid Token:', err);
     }
     ```

5. **Moment.js** (Note: It's now in maintenance mode and they suggest using alternatives like date-fns or Luxon):
   - A library for parsing, validating, manipulating, and formatting dates.
