export const getRelationStringForId=(id, first, second, showReverseString=false)=>{
    if(!id) return '';
    const rel= getRelationObjectForId(id);
    if(rel){
        let f='';
        let s= '';
        let rs='';
        let rev='';
        if(!showReverseString){
            f=first;
            s=second;
            rs=rel.name;
            rev=rel.reverseName;
        }else{
            f=second;
            s=first;
            rs=rel.reverseName;
            rev=rel.name;
        }
        return `if '${f}' '${rs}' '${s}' , then '${s}' '${rev}' '${f}' `;
    }else{
        return '';
    }
}

