// RelatedNode.model.js
const mongoose = require("mongoose");
const { v4: uuidv4 } = require("uuid");

const relationSchema = new mongoose.Schema({
    uniqueId: { type: String, default: () => uuidv4(), unique: true },
    name: {
        type: String,
        required: true,
        validate: {
            validator: function (v) {
                return v.trim().length > 0;
            },
            message: "Name cannot be an empty string or a string that trims to zero length",
        },
    },
    type: {
        type: String,
        enum: ["previous", "next"],
        required: true,
    },
    hasId: { type: String },
    withId: { type: String },
});

const relatedNodeSchema = new mongoose.Schema({
    uniqueId: {
        type: String,
        default: () => uuidv4(),
        unique: true,
        required: true,
    },
    name: {
        type: String,
        required: true,
        validate: {
            validator: function (v) {
                return v.trim().length > 0;
            },
            message: "Name cannot be an empty string or a string that trims to zero length",
        },
    },
    itemType: {
        type: String,
        enum: [
            "category",
            "question",
            "topic",
            "section",
            "link",
            "tech-stack",
            "memory-map",
            "conversation",
            "message"
        ],
        required: true,
    },
    relations: [relationSchema],
});

// Virtuals to derive previousRelations and nextRelations
relatedNodeSchema.virtual('previousRelations').get(function () {
    return this.relations.filter(relation => relation.type === "previous");
});

relatedNodeSchema.virtual('nextRelations').get(function () {
    return this.relations.filter(relation => relation.type === "next");
});

// Pre-save hook to ensure uniqueId is generated if not set
relatedNodeSchema.pre('save', function (next) {
    if (!this.uniqueId) {
        this.uniqueId = uuidv4();
    }
    next();
});

// Enable virtuals to be included in JSON and object output
relatedNodeSchema.set('toJSON', { virtuals: true });
relatedNodeSchema.set('toObject', { virtuals: true });

const RelatedNode = mongoose.model("RelatedNode", relatedNodeSchema);

module.exports = { RelatedNode };
```

### Key Changes:
- **Virtuals**: Added `previousRelations` and `nextRelations` virtuals that automatically filter the `relations` array based on the `type` field.
- **Simplified Schema**: Removed `createdDate`, `updatedDate`, and `softDelete` fields to focus on the essential aspects.
- **Pre-save Hook**: Simplified the uniqueId generation logic for clarity.

