              'public',
              'class',
              'static',
              'void',
              'if',
              'else',
              'for',
              'while',
              'do',
              'switch',
            ].includes(word);

            // Check if the word is a comment
            const isComment =
              word.startsWith('//') || word.startsWith('/*');

            // Apply styles based on the type of word
            if (isKeyword) {
              return (
                <span key={wordIndex} style={keywordStyle}>
                  {word}&nbsp;
                </span>
              );
            } else if (isComment) {
              return (
                <span key={wordIndex} style={commentStyle}>
                  {word}&nbsp;
                </span>
              );
            } else {
              return (
                <span key={wordIndex}>
                  {word}&nbsp;
                </span>
              );
            }
          })}
        </div>
      );
    });
  };

  return <pre style={codeStyle}>{highlightCode(code)}</pre>;
};

export default CodeHighlighter;
