```java
package com.example.crud.controller;

import com.example.crud.model.Student;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.client.RestTemplate;

import java.util.Arrays;
import java.util.List;

@Controller
public class StudentController {

    private static final String BASE_URL = "http://localhost:3000/students";

    private final RestTemplate restTemplate;

    public StudentController(RestTemplate restTemplate) {
        this.restTemplate = restTemplate;
    }

    @GetMapping("/")
    public String index(Model model) {
        List<Student> students = Arrays.asList(restTemplate.getForObject(BASE_URL, Student[].class));
        model.addAttribute("students", students);
        return "index";
    }

    @GetMapping("/add")
    public String addStudentForm(Model model) {
        model.addAttribute("student", new Student());
        return "addStudent";
    }

    @PostMapping("/add")
    public String addStudent(@ModelAttribute Student student) {
        restTemplate.postForObject(BASE_URL, student, Student.class);
        return "redirect:/";
    }

    @GetMapping("/edit/{id}")
    public String editStudentForm(@PathVariable int id, Model model) {
        Student student = restTemplate.getForObject(BASE_URL + "/" + id, Student.class);
        model.addAttribute("student", student);
        return "editStudent";
    }

    @PostMapping("/edit/{id}")
    public String editStudent(@PathVariable int id, @ModelAttribute Student student) {
        restTemplate.put(BASE_URL + "/" + id, student);
        return "redirect:/";
    }

    @GetMapping("/delete/{id}")
    public String deleteStudent(@PathVariable int id) {
        restTemplate.delete(BASE_URL + "/" + id);
        return "redirect:/";
    }
}
```

