2. **Update `StudentComponent.vue` with Dynamic Styles**

```vue
<!-- src/components/StudentComponent.vue -->
<template>
  <div>
    <h1 :style="styles.header">Student List</h1>
    <ul>
      <li v-for="student in students" :key="student.id" :style="styles.listItem">
        {{ student.name }} ({{ student.age }})
        <button :style="styles.button" @click="edit(student)">Edit</button>
        <button :style="styles.button" @click="deleteStudent(student.id)">Delete</button>
      </li>
    </ul>

    <h2 :style="styles.header">Add New Student</h2>
    <form @submit.prevent="addStudent" :style="styles.form">
      <input v-model="newStudent.name" placeholder="Name" required :style="styles.input">
      <input v-model="newStudent.age" type="number" placeholder="Age" required :style="styles.input">
      <button type="submit" :style="styles.button">Add</button>
    </form>

    <div v-if="editStudent">
      <h2 :style="styles.header">Edit Student</h2>
      <form @submit.prevent="updateStudent" :style="styles.form">
        <input v-model="editStudent.name" placeholder="Name" required :style="styles.input">
        <input v-model="editStudent.age" type="number" placeholder="Age" required :style="styles.input">
        <button type="submit" :style="styles.button">Update</button>
        <button type="button" @click="cancelEdit" :style="styles.button">Cancel</button>
      </form>
    </div>
  </div>
</template>

<script>
import axios from 'axios';

export default {
  data() {
    return {
      students: [],
      newStudent: { id: 0, name: '', age: 0 },
      editStudent: null,
      styles: {
        header: {
          color: 'blue',
          textAlign: 'center',
        },
        listItem: {
          margin: '10px 0',
        },
        button: {
          margin: '0 5px',
          padding: '5px 10px',
          backgroundColor: 'lightblue',
          border: 'none',
          cursor: 'pointer',
        },
        form: {
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
        },
        input: {
          margin: '5px 0',
          padding: '5px',
          borderRadius: '3px',
          border: '1px solid #ccc',
        },
      }
    };
  },
  methods: {
    loadStudents() {
      axios.get('http://localhost:3000/students').then(response => {
        this.students = response.data;
      });
    },
    addStudent() {
      axios.post('http://localhost:3000/students', this.newStudent).then(response => {
        this.students.push(response.data);
        this.newStudent = { id: 0, name: '', age: 0 };
      });
    },
    updateStudent() {
      axios.put(`http://localhost:3000/students/${this.editStudent.id}`, this.editStudent).then(() => {
        this.loadStudents();
        this.editStudent = null;
      });
    },
    deleteStudent(id) {
      axios.delete(`http://localhost:3000/students/${id}`).then(() => {
        this.loadStudents();
      });
    },
    edit(student) {
      this.editStudent = { ...student };
    },
    cancelEdit() {
      this.editStudent = null;
    },
  },
  mounted() {
    this.loadStudents();
  },
};
</script>

