  }

  addStudent() {
    this.http.post('http://localhost:3000/students', this.newStudent).subscribe(response => {
      this.students$ = this.http.get<any[]>('http://localhost:3000/students');
      this.newStudent = { name: '', age: 0 };
    });
  }

  updateStudent() {
    this.http.put(`http://localhost:3000/students/${this.editStudent.id}`, this.editStudent).subscribe(() => {
      this.students$ = this.http.get<any[]>('http://localhost:3000/students');
      this.editStudent = null;
    });
  }

  deleteStudent(id: number) {
    this.http.delete(`http://localhost:3000/students/${id}`).subscribe(() => {
      this.students$ = this.http.get<any[]>('http://localhost:3000/students');
    });
  }

  edit(student: any) {
    this.editStudent = { ...student };
  }

  cancelEdit() {
    this.editStudent = null;
  }
}
```

### 3. **Update `main.ts`**

In Angular 18, you can use `bootstrapApplication` for a more streamlined bootstrapping process if you use standalone components.

```typescript
// src/main.ts
import { bootstrapApplication } from '@angular/platform-browser';
import { AppComponent } from './app/app.component';
import { provideRouter } from '@angular/router';
import { AppRoutingModule } from './app/app-routing.module';

bootstrapApplication(AppComponent, {
  providers: [
    provideRouter(AppRoutingModule)
  ]
}).catch(err => console.error(err));
```

### 4. **HttpClientModule**

Ensure `HttpClientModule` is imported in your `app.module.ts` if you're not using standalone components.

```typescript
// src/app/app.module.ts
