    AppRoutingModule,
    HttpClientModule
  ],
  providers: [],
  bootstrap: [AppComponent]
})
export class AppModule { }
```

### 5. **Routing with Standalone Components**

If you’re using standalone components and routing, you can define routes directly within the `bootstrapApplication` call.

```typescript
// src/main.ts
import { bootstrapApplication } from '@angular/platform-browser';
import { provideRouter, RouterModule } from '@angular/router';
import { AppComponent } from './app/app.component';
import { StudentComponent } from './app/student/student.component';

bootstrapApplication(AppComponent, {
  providers: [
    provideRouter([
      { path: '', component: StudentComponent }
    ])
  ]
}).catch(err => console.error(err));
```

### Summary

1. **Use Standalone Components:** Mark components with `standalone: true`.
2. **HttpClient:** Use `HttpClient` for HTTP requests.
3. **Streamlined Bootstrapping:** Use `bootstrapApplication` in `main.ts` for a more modern approach.
4. **Routing:** Define routes directly in the `bootstrapApplication` providers.

By adapting to these updates, you’ll be utilizing Angular 18's new features and improvements effectively.

