You can create a method in your Mongoose router or a separate utility file to retrieve the names of all ancestors of a given Link. Here's how you can implement it:

```javascript
// Import necessary modules and models
const express = require('express');
const router = express.Router();
const Link = require('../models/Link');

// Recursive function to get all ancestors of a link
async function getAllAncestors(parentId, ancestors = []) {
  const link = await Link.findOne({ uniqueId: parentId });
  if (!link || !link.parentId) {
    return ancestors;
  }
  ancestors.unshift(link.name); // Add the name of the current link to ancestors array
  return getAllAncestors(link.parentId, ancestors); // Recursively call to get ancestors of the parent link
}

// Route to get names of all ancestors of a link
router.get('/ancestors/:parentId', async (req, res) => {
  try {
    const ancestors = await getAllAncestors(req.params.parentId);
    res.json(ancestors);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

module.exports = router;
```

In this code:

- We define a recursive function `getAllAncestors` that takes a `parentId` and an `ancestors` array as arguments. It retrieves the link with the provided `parentId`, adds its name to the `ancestors` array, and recursively calls itself with the parent's `parentId` until there are no more ancestors.
