```java
import com.vladsch.flexmark.ast.Node;
import com.vladsch.flexmark.parser.Parser;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

@RestController
public class MetadataController {

    @PostMapping("/extract-metadata")
    public Set<String> extractMetadata(@RequestBody String markdownText) {
        Set<String> techStacks = new HashSet<>();
        Parser parser = Parser.builder().build();
        Node document = parser.parse(markdownText);

        document.accept(node -> {
            if (node.getChars().startsWith("**Tech Stack:**")) {
                String techStack = node.getChars().toString().replace("**Tech Stack:**", "").trim();
                String[] stackArray = techStack.split(", ");
                for (String stack : stackArray) {
                    techStacks.add(stack.trim());
                }
            }
            return true;
        });

        return techStacks;
    }
}
```

This controller defines a `POST` endpoint `/extract-metadata` that accepts Markdown text in the request body. It then extracts the tech stacks mentioned in the Markdown text and returns them as a set.

5. **Run the application**: Run your Spring Boot application, and you can make a `POST` request to the `/extract-metadata` endpoint with your Markdown text as the request body.

