Got it! You can run the `processText()` logic when the component is loaded by using the `useEffect()` hook with an empty dependency array `[]`. This ensures that the logic inside `useEffect()` runs only once when the component is mounted. Here's the updated `MetadataExtractor` component:

```jsx
import React, { useState, useEffect } from 'react';
import yaml from 'js-yaml';

const MetadataExtractor = ({ rawText, textType }) => {
    const [errorMessage, setErrorMessage] = useState('');
    const [metadata, setMetadata] = useState(null);

    useEffect(() => {
        const processText = () => {
            let metadata = {};
            let error = '';

            if (textType === 'yaml') {
                try {
                    metadata = yaml.load(rawText);
                } catch (e) {
                    if (e.mark) {
                        // If the error has 'mark' property, it contains line and column information
                        const errorLine = e.mark.line + 1; // Adjust for 0-based index
                        error = `Error parsing YAML at line ${errorLine}: ${e.message}`;
                    } else {
                        // If the error does not have 'mark' property, it's a general parsing error
                        error = `Error parsing YAML: ${e.message}`;
                    }
                }
            } else {
                // Handle other text types (Markdown, plain text) here
                error = 'Text type is not supported yet.';
            }

            setErrorMessage(error);
            setMetadata(metadata);
        };

        processText();
    }, [rawText, textType]); // Run when rawText or textType changes

    return (
        <div>
            {errorMessage && <p className="error">{errorMessage}</p>}
            {metadata && (
                <div>
                    <h2>Metadata:</h2>
                    <pre>{JSON.stringify(metadata, null, 2)}</pre>
                </div>
            )}
        </div>
    );
};

export default MetadataExtractor;
```

With this modification, the `processText()` logic will run automatically when the component is mounted or when the `rawText` or `textType` props change. The `useEffect()` hook with an empty dependency array ensures that the logic inside it runs only once when the component is mounted.

