                for (SpeechRecognitionResult result : response.getResultsList()) {
                    for (SpeechRecognitionAlternative alternative : result.getAlternativesList()) {
                        System.out.printf("Transcription: %s%n", alternative.getTranscript());
                    }
                }
            }

