           <scope>test</scope>
       </dependency>
   </dependencies>
   ```

4. **Download OpenNLP Models**:

   Download the necessary OpenNLP models from the [Apache OpenNLP Models page](https://opennlp.apache.org/models.html), such as the `en-ner-location.bin` model for named entity recognition.

5. **Create the Controller**:

   Create a controller class to handle incoming requests and perform NLP tasks. Here's an example:

   ```java
   package com.example.nlp;

   import opennlp.tools.namefind.NameFinderME;
   import opennlp.tools.namefind.TokenNameFinderModel;
   import opennlp.tools.tokenize.SimpleTokenizer;
   import opennlp.tools.util.Span;
   import org.springframework.web.bind.annotation.GetMapping;
   import org.springframework.web.bind.annotation.RequestParam;
   import org.springframework.web.bind.annotation.RestController;

   import java.io.InputStream;
   import java.util.HashMap;
   import java.util.Map;

   @RestController
   public class NlpController {

       private static final Map<String, String> countryCapitalMap = new HashMap<>();

       static {
           countryCapitalMap.put("India", "New Delhi");
           countryCapitalMap.put("USA", "Washington, D.C.");
           countryCapitalMap.put("France", "Paris");
           countryCapitalMap.put("Germany", "Berlin");
           // Add more countries and their capitals as needed
       }

       @GetMapping("/getCapital")
       public String getCapital(@RequestParam String question) {
           try {
               // Load the OpenNLP model for named entity recognition
               InputStream modelIn = getClass().getResourceAsStream("/models/en-ner-location.bin");
               TokenNameFinderModel model = new TokenNameFinderModel(modelIn);
               NameFinderME nameFinder = new NameFinderME(model);

               // Tokenize the input question
               SimpleTokenizer tokenizer = SimpleTokenizer.INSTANCE;
               String[] tokens = tokenizer.tokenize(question);

               // Find named entities in the tokens
               Span[] spans = nameFinder.find(tokens);
               String country = null;
               for (Span span : spans) {
                   country = tokens[span.getStart()];
               }

               if (country != null && countryCapitalMap.containsKey(country)) {
                   return "The capital of " + country + " is " + countryCapitalMap.get(country) + ".";
               } else {
                   return "Sorry, I couldn't find the capital for the given country.";
               }
           } catch (Exception e) {
               e.printStackTrace();
               return "An error occurred while processing the request.";
           }
       }
   }
   ```

6. **Run the Application**:

   Run the Spring Boot application using the following command:

   ```sh
